      const G={};const order=[];X.forEach(t=>{const k=key(t);if(!G[k]){G[k]=[];order.push(k)}G[k].push(t)});
      if(o.group==='cat')order.sort((a,b)=>sum(G[b],'exp')+sum(G[b],'inc')-sum(G[a],'exp')-sum(G[a],'inc'));
