  const head=`<header class="rh"><div><div class="rapp">${REP_LOGO}إدارة شؤوني</div><h1>${esc(R.label)}</h1><div class="rper">الفترة: من ${fmtD(R.from)} إلى ${fmtD(R.to)}${payMode()?' (الشهر من الراتب إلى الراتب)':''}</div></div><div class="rmeta">${repOwner()}أُعدّ في ${fmtD(today())} الساعة ${String(now.getHours()).padStart(2,'0')}:${String(now.getMinutes()).padStart(2,'0')}<br>العملة: الريال العُماني (ر.ع.)${o.secs.includes('review')||o.reviewCols?'<br>راجعه: ____________':''}</div></header>`;
  const sign=o.sign===false?'':`<section class="sign"><div class="sg-n"><span>ملاحظات</span><i></i><i></i></div><div class="sg-a"><span>المراجعة والاعتماد</span><div><em>الاسم</em><em>التوقيع</em><em>التاريخ</em></div></div></section>`;
